const config = {
  "previewFeatures": [
    "driverAdapters"
  ],
  "clientVersion": "7.10.0",
  "engineVersion": "0edf323efd1d98336f3f0a68684b56f689b900d3",
  "activeProvider": "postgresql",
  "inlineSchema": "generator client {\n  provider        = \"prisma-client-js\"\n  output          = \"../src/generated/prisma\"\n  previewFeatures = [\"driverAdapters\"]\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ──────────────────────────────────────────\n// USUARIO\n// Espejo local de Supabase Auth: la autenticación (email +\n// password) vive 100% en Supabase (auth.users), acá solo se\n// guarda el rol y el nombre para mostrar en la UI. supabaseUserId\n// es el id (UUID) que devuelve Supabase Auth al crear la cuenta.\n// ──────────────────────────────────────────\nmodel Usuario {\n  id                           Int                   @id @default(autoincrement())\n  supabaseUserId               String                @unique\n  nombre                       String\n  esAdmin                      Boolean               @default(false)\n  esAdminKpis                  Boolean               @default(false) // gestiona accesos de KPIs/ISO de otros; no implica acceso propio automático\n  activo                       Boolean               @default(true) // false = sin acceso al sistema pero conserva historial (ver PATCH /usuarios/:id/activo)\n  // Refrigerio de cada usuario, en minutos desde medianoche (ej. 720 = 12:00pm). Null = sin\n  // configurar, no se descuenta nada. Es escalonado por persona (ver PATCH /usuarios/:id/refrigerio,\n  // exclusivo de Admin) — AlertasPedidosService lo usa para no contar el refrigerio como horas\n  // hábiles al calcular si un pedido lleva 48h sin entregarse.\n  refrigerioInicioMinutos      Int?\n  refrigerioFinMinutos         Int?\n  // Quién y cuándo desactivó la cuenta (null si está activa). Si ese admin se\n  // elimina después, desactivadoPorId queda en null pero desactivadoEn se conserva.\n  desactivadoEn                DateTime?\n  desactivadoPorId             Int?\n  desactivadoPor               Usuario?              @relation(\"UsuarioDesactivadoPor\", fields: [desactivadoPorId], references: [id], onDelete: SetNull)\n  desactivados                 Usuario[]             @relation(\"UsuarioDesactivadoPor\")\n  avatarUrl                    String?\n  permisos                     Permiso[]\n  createdAt                    DateTime              @default(now())\n  trabajosImpresion            TrabajoImpresion[]\n  archivosSubidos              Archivo[]\n  accesosIndicador             AccesoIndicador[]\n  accesoIso                    AccesoISO?\n  pedidosCreados               Pedido[]              @relation(\"PedidosCreados\")\n  pedidosEditados              Pedido[]              @relation(\"PedidosEditados\")\n  notificaciones               Notificacion[]\n  cotizacionesCreadas          Cotizacion[]          @relation(\"CotizacionesCreadas\")\n  cotizacionesEditadas         Cotizacion[]          @relation(\"CotizacionesEditadas\")\n  cotizacionesHistorialEditado CotizacionHistorial[]\n  ausencias                    Ausencia[]            @relation(\"AusenciasDelUsuario\")\n  ausenciasRegistradas         Ausencia[]            @relation(\"AusenciasRegistradas\")\n  suscripcionesPush            SuscripcionPush[]\n}\n\nmodel Permiso {\n  id            Int     @id @default(autoincrement())\n  usuarioId     Int\n  usuario       Usuario @relation(fields: [usuarioId], references: [id], onDelete: Cascade)\n  recurso       Recurso\n  puedeVer      Boolean @default(false)\n  puedeCrear    Boolean @default(false)\n  puedeEditar   Boolean @default(false)\n  puedeEliminar Boolean @default(false)\n\n  @@unique([usuarioId, recurso])\n}\n\nenum Recurso {\n  LOTES\n  PRODUCTOS\n  FABRICANTES\n  PLANTILLAS\n  USUARIOS\n  ETIQUETAS\n  PEDIDOS\n  // Antes Cotizaciones compartía PEDIDOS (mismo flujo de Joel). Se separó porque los\n  // encargados son personas distintas: Charlie solo Pedidos, Joel solo Cotizaciones,\n  // Alice ve ambos — hacía falta poder otorgar uno sin el otro.\n  COTIZACIONES\n  // Clientes también compartía PEDIDOS (\"solo alimenta el autocomplete\"), pero es un\n  // recurso propio con encargados distintos a Pedidos y a Cotizaciones — mismo motivo\n  // que la separación de arriba.\n  CLIENTES\n  // Gatea la pantalla de Registro de limpieza del frontend (link a un Google Form +\n  // historial leído de un CSV publicado). No tiene controller propio en el backend:\n  // no hay datos de este recurso en la base, solo controla ver/entrar a la pantalla.\n  REGISTRO_LIMPIEZA\n}\n\n// ──────────────────────────────────────────\n// FABRICANTE\n// Un fabricante puede proveer varios lotes (1:N), incluso de\n// productos distintos. No se permite repetir nombre — se valida\n// con nombreNormalizado (minúsculas + sin acentos) para evitar\n// duplicados tipo \"Ácido Cítrico\" vs \"acido citrico\".\n\n// ──────────────────────────────────────────\nmodel Fabricante {\n  id                Int      @id @default(autoincrement())\n  nombre            String   @unique\n  nombreNormalizado String   @unique\n  lotes             Lote[]\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  @@map(\"fabricantes\")\n}\n\n// ──────────────────────────────────────────\n// PRODUCTO\n// Ya NO tiene fabricante fijo: un mismo producto puede tener\n// lotes de distintos fabricantes a lo largo del tiempo (el\n// fabricante varía por lote, no por producto). Nombre único a\n// nivel global.\n// ──────────────────────────────────────────\nmodel Producto {\n  id                 Int      @id @default(autoincrement())\n  nombre             String   @unique\n  nombreNormalizado  String   @unique\n  nfpaSalud          Int? // 0-4\n  nfpaInflamabilidad Int? // 0-4\n  nfpaReactividad    Int?\n  // Densidad en g/ml. Solo hace falta para líquidos (neto en ML/L): con ella la\n  // tara se calcula como bruto - neto × densidad. Null = no se calcula tara.\n  densidad           Float?\n  // Pictogramas GHS/SGA que aplican: 'GHS01'..'GHS09'. Se muestran en la página del QR.\n  pictogramasGhs     String[] @default([])\n  // 'PELIGRO' | 'ATENCION' (palabra de advertencia GHS) y las frases H/P de la FDS,\n  // una por elemento (ej. 'H314: Provoca quemaduras graves en la piel...').\n  palabraAdvertencia String?\n  frasesH            String[] @default([])\n  frasesP            String[] @default([])\n  // Path del objeto en el bucket, ej: \"ficha-seguridad/producto-12/1234-ficha.pdf\".\n  // Opcional: un producto se puede registrar sin ficha y adjuntarla despues.\n  fichaSeguridadUrl  String?\n  // Idem, ej: \"ficha-tecnica/producto-12/1234-ficha.pdf\". Opcional.\n  fichaTecnicaUrl    String?\n  lotes              Lote[]\n  createdAt          DateTime @default(now())\n  updatedAt          DateTime @updatedAt\n\n  @@map(\"productos\")\n}\n\n// ──────────────────────────────────────────\n// PLANTILLA\n// Independiente de Producto — se elige recién al generar la etiqueta.\n// ──────────────────────────────────────────\nmodel Plantilla {\n  id                Int                @id @default(autoincrement())\n  nombre            String             @unique\n  archivo           String\n  activa            Boolean            @default(true)\n  createdAt         DateTime           @default(now())\n  updatedAt         DateTime           @updatedAt\n  trabajosImpresion TrabajoImpresion[]\n\n  @@map(\"plantillas\")\n}\n\n// ──────────────────────────────────────────\n// LOTE\n// Acá vive la relación real con Fabricante: cada lote de un\n// producto puede venir de un fabricante distinto. Único por\n// producto + fabricante + número de lote (un mismo número de\n// lote podría repetirse entre fabricantes distintos, así que\n// fabricanteId entra en el constraint para no chocar por error).\n//\n// fechaFabricacion / fechaVencimiento van como String (no DateTime):\n// en el COA aparecen en formatos distintos según el proveedor —\n// a veces solo mes/año (\"10/2025\"), a veces día/mes/año\n// (\"11/10/2025\") — y se guarda tal cual se digita, sin forzar\n// un único formato de fecha ni perder esa información.\n// ──────────────────────────────────────────\nmodel Lote {\n  id                    Int                @id @default(autoincrement())\n  numeroLote            String\n  fechaFabricacion      String\n  fechaVencimiento      String\n  // Se calcula automáticamente en el service a partir de fechaVencimiento\n  // (parseando \"MM/AAAA\" como último día de ese mes, o \"DD/MM/AAAA\" tal cual).\n  // Nunca se edita a mano — solo existe para poder ordenar/filtrar\n  // (\"lotes que vencen este mes\") sin tocar el texto original.\n  fechaVencimientoOrden DateTime?          @db.Date\n  coaUrl                String? // path del objeto en el bucket, ej: \"lote-123/coa.pdf\"\n  productoId            Int\n  producto              Producto           @relation(fields: [productoId], references: [id], onDelete: Restrict)\n  fabricanteId          Int\n  fabricante            Fabricante         @relation(fields: [fabricanteId], references: [id], onDelete: Restrict)\n  createdAt             DateTime           @default(now())\n  updatedAt             DateTime           @updatedAt\n  trabajosImpresion     TrabajoImpresion[]\n\n  @@unique([productoId, fabricanteId, numeroLote])\n  @@index([numeroLote])\n  @@index([fabricanteId])\n  @@map(\"lotes\")\n}\n\nenum EstadoTrabajoImpresion {\n  PENDIENTE\n  IMPRESO\n  ERROR\n}\n\nmodel TrabajoImpresion {\n  id              Int                    @id @default(autoincrement())\n  loteId          Int\n  lote            Lote                   @relation(fields: [loteId], references: [id])\n  plantillaId     Int\n  plantilla       Plantilla              @relation(fields: [plantillaId], references: [id])\n  pesoBruto       String\n  unidadBruto     String\n  cantidadNeta    String?\n  unidadNeta      String\n  tara            String?\n  // Código imposible de adivinar que va en el QR impreso; permite abrir la\n  // página pública de trazabilidad de ESTA etiqueta (con sus pesos reales)\n  // sin exponer ids autoincrementales. Null en trabajos anteriores al QR.\n  token           String?                @unique\n  // Cuántas veces se abrió la página pública de este QR y cuándo fue la última.\n  escaneos        Int                    @default(0)\n  ultimoEscaneoAt DateTime?\n  // Cuántas veces, desde esa misma página pública, se vio/descargó el COA o\n  // se vio la ficha de seguridad (FDS). Contadores aparte de `escaneos`\n  // porque un escaneo no implica abrir ninguno de los dos documentos.\n  coaVistas       Int                    @default(0)\n  coaDescargas    Int                    @default(0)\n  fdsVistas       Int                    @default(0)\n  proforma        String\n  imagenPath      String?\n  estado          EstadoTrabajoImpresion @default(PENDIENTE)\n  mensajeError    String?\n  creadoPorId     Int\n  creadoPor       Usuario                @relation(fields: [creadoPorId], references: [id])\n  createdAt       DateTime               @default(now())\n  updatedAt       DateTime               @updatedAt\n\n  @@map(\"trabajos_impresion\")\n}\n\n// ──────────────────────────────────────────\n// MÓDULO PEDIDOS / TIEMPO DE ENTREGA\n// Reemplaza el registro manual en Excel del lead time de pedidos.\n// Cada fecha/hora de etapa (preparadoEn, salioEn, entregadoEn) se\n// precarga con la hora actual al marcarla desde la UI, pero queda\n// editable después — a diferencia de createdAt/updatedAt (automáticos,\n// solo para trazabilidad interna, nunca se muestran como \"dato a llenar\").\n// No hay un campo `estado` propio: la etapa se deriva de qué timestamps\n// están seteados (evita que quede desincronizado de la fecha real).\n// ──────────────────────────────────────────\nenum TipoDocumentoCliente {\n  RUC\n  DNI\n  CARNET_EXTRANJERIA\n}\n\nmodel Cliente {\n  id                 Int                   @id @default(autoincrement())\n  nombre             String                @unique\n  nombreNormalizado  String                @unique\n  tipoDocumento      TipoDocumentoCliente?\n  numeroDocumento    String?\n  direccion          String?\n  celular            String?\n  // Correo donde se avisa al cliente de su pedido (salio / entregado). Opcional: sin correo no se envia nada.\n  email              String?\n  // Cuando el personal registró que informó al cliente y este autorizó el uso de sus\n  // datos de contacto (celular/correo) para avisarle de sus pedidos. Null = sin registro\n  // (por ejemplo, clientes cargados antes de existir este campo).\n  autorizaContactoEn DateTime?\n  createdAt          DateTime              @default(now())\n  pedidos            Pedido[]\n  cotizaciones       Cotizacion[]\n\n  @@map(\"clientes\")\n}\n\n// Motivo por el que un pedido se sale de lo normal — cubre tanto demoras\n// de preparación (falta de insumo) como formas de entrega o cierre\n// distintas a la venta normal. Es un solo campo por pedido, no por etapa:\n// en la práctica el Excel nunca tuvo más de una observación relevante por\n// fila.\nenum CategoriaObservacionPedido {\n  INSUMO_EN_IMPORTACION\n  INSUMO_SIN_STOCK\n  RECOGE_EN_ALMACEN\n  IMPORTACION_EXPORTACION\n  CANCELADO\n  OTRO\n}\n\nmodel Pedido {\n  id                              Int                         @id @default(autoincrement())\n  clienteId                       Int\n  cliente                         Cliente                     @relation(fields: [clienteId], references: [id], onDelete: Restrict)\n  numeroProforma                  String                      @unique\n  // Llave del enlace público de seguimiento (/p/<token>): la genera la base, 122 bits aleatorios.\n  // Es lo único que protege esa página, así que nunca debe ser el id ni algo predecible.\n  tokenSeguimiento                String                      @unique @default(dbgenerated(\"replace((gen_random_uuid())::text, '-'::text, ''::text)\"))\n  recibidoEn                      DateTime                    @default(now())\n  inicioPreparacionEn             DateTime?\n  preparadoEn                     DateTime?\n  salioEn                         DateTime?\n  entregadoEn                     DateTime?\n  // Cuando se le aviso al cliente por correo. Sirve para no avisar dos veces la misma etapa\n  // (por ejemplo, si alguien corrige la fecha despues).\n  avisoSalioEnviadoEn             DateTime?\n  avisoEntregadoEnviadoEn         DateTime?\n  // Cuándo se creó la notificación interna de \"pedido vencido\" (ver NotificacionesModule /\n  // AlertasPedidosService). Evita mandarla dos veces, mismo patrón que los avisos de arriba.\n  // Solo aplica mientras salioEn sigue null — en cuanto sale, la alerta pasa a medir desde\n  // salioEn (alertaSalioSinEntregarEnviadaEn), nunca las dos a la vez para el mismo pedido.\n  alerta48hEnviadaEn              DateTime?\n  alertaSalioSinEntregarEnviadaEn DateTime?\n  categoriaObservacion            CategoriaObservacionPedido?\n  detalleObservacion              String?\n  creadoPorId                     Int\n  creadoPor                       Usuario                     @relation(\"PedidosCreados\", fields: [creadoPorId], references: [id])\n  ultimoEditadoPorId              Int?\n  ultimoEditadoPor                Usuario?                    @relation(\"PedidosEditados\", fields: [ultimoEditadoPorId], references: [id])\n  createdAt                       DateTime                    @default(now())\n  updatedAt                       DateTime                    @updatedAt\n  notificaciones                  Notificacion[]\n\n  @@index([clienteId])\n  // Cubren el WHERE de AlertasPedidosService.avisarSinSalir/avisarSalioSinEntregar (cron cada\n  // 30 min, src/pedidos/alertas-pedidos.service.ts): columnas de igualdad/IS NULL primero, el\n  // rango de fecha al final, mismo criterio que los índices de Cotizacion abajo.\n  @@index([alerta48hEnviadaEn, entregadoEn, salioEn, recibidoEn])\n  @@index([alertaSalioSinEntregarEnviadaEn, entregadoEn, salioEn])\n  @@map(\"pedidos\")\n}\n\n// Notificación interna (no correo) para avisar dentro del sistema, ej. \"este pedido lleva\n// más de 48h hábiles sin marcarse como entregado\" (AlertasPedidosService) o \"esta cotización\n// está aprobada hace más de 1h sin avisar a almacén\" (AlertasCotizacionesService). El aviso al\n// CLIENTE de un pedido (salió/entregado) sigue siendo un correo externo vía n8n — ver CLAUDE.md;\n// esto es solo para avisos internos al personal (quien tiene acceso al recurso + los admins).\nmodel Notificacion {\n  id           Int              @id @default(autoincrement())\n  usuarioId    Int\n  usuario      Usuario          @relation(fields: [usuarioId], references: [id], onDelete: Cascade)\n  tipo         TipoNotificacion\n  mensaje      String\n  pedidoId     Int?\n  pedido       Pedido?          @relation(fields: [pedidoId], references: [id], onDelete: Cascade)\n  cotizacionId Int?\n  cotizacion   Cotizacion?      @relation(fields: [cotizacionId], references: [id], onDelete: Cascade)\n  leidaEn      DateTime?\n  createdAt    DateTime         @default(now())\n\n  @@index([usuarioId])\n  @@map(\"notificaciones\")\n}\n\nenum TipoNotificacion {\n  PEDIDO_VENCIDO\n  PEDIDO_SALIO_SIN_ENTREGAR\n  COTIZACION_SIN_AVISO_ALMACEN\n  COTIZACION_RESPUESTA_LENTA\n  RESUMEN_DIARIO\n}\n\n// Suscripción del navegador a Web Push (PushSubscription del navegador), una fila por\n// dispositivo/navegador. endpoint es único: si el usuario se vuelve a suscribir desde el mismo\n// navegador (ej. reinstaló), se reasigna en vez de duplicar (ver PushService.suscribir).\nmodel SuscripcionPush {\n  id        Int      @id @default(autoincrement())\n  usuarioId Int\n  usuario   Usuario  @relation(fields: [usuarioId], references: [id], onDelete: Cascade)\n  endpoint  String   @unique\n  p256dh    String\n  auth      String\n  createdAt DateTime @default(now())\n\n  @@index([usuarioId])\n  @@map(\"suscripciones_push\")\n}\n\n// Seguimiento del proceso de cotización de Joel: mismo patrón que Pedido (fechas por etapa,\n// sin columna \"estado\" propia — se deriva de cuáles están seteadas, ver derivarEstadoCotizacion\n// en cotizaciones.service.ts). Insumos, cantidades y precio quedan en KEYFACIL ERP, acá solo se\n// registran los 4 momentos que hoy Katherine carga a mano en Excel (DS del indicador comercial):\n// llega el pedido del cliente -> Joel cotiza -> el cliente aprueba -> Joel avisa a almacén.\nmodel Cotizacion {\n  id                    Int                         @id @default(autoincrement())\n  clienteId             Int\n  cliente               Cliente                     @relation(fields: [clienteId], references: [id], onDelete: Restrict)\n  // Número de proforma de KEYFACIL (siempre \"PF01-...\"). Nulo hasta que Joel cotiza: no existe\n  // todavía cuando recién llega el pedido del cliente. Postgres permite varios NULL en una\n  // columna @unique, así que no choca entre sí mientras no se haya cotizado.\n  numeroProforma        String?                     @unique\n  notas                 String?\n  requerimientoEn       DateTime                    @default(now())\n  cotizacionEnviadaEn   DateTime?\n  pedidoAprobadoEn      DateTime?\n  avisoAlmacenEn        DateTime?\n  // Cuándo se mandó el recordatorio de \"falta avisar a almacén\" (aprobado hace más de 1h sin\n  // avisoAlmacenEn). Null = todavía no hizo falta. Evita mandar el mismo recordatorio dos veces.\n  recordatorioEnviadoEn DateTime?\n  // Cuándo se avisó que la cotización tarda en enviarse (requerimientoEn viejo sin\n  // cotizacionEnviadaEn) — ver AlertasCotizacionesService. Mismo criterio de \"una sola vez\".\n  alertaLentaEnviadaEn  DateTime?\n  // Mismo campo de excepción que Pedido (ver CategoriaObservacionPedido arriba): se reutiliza el\n  // mismo enum a propósito, para que \"Insumo sin stock\"/\"Cancelado\"/etc. signifiquen lo mismo y se\n  // puedan comparar en los reportes, en vez de mantener dos catálogos que dicen lo mismo con otro\n  // nombre.\n  categoriaObservacion  CategoriaObservacionPedido?\n  detalleObservacion    String?\n  creadoPorId           Int\n  creadoPor             Usuario                     @relation(\"CotizacionesCreadas\", fields: [creadoPorId], references: [id])\n  ultimoEditadoPorId    Int?\n  ultimoEditadoPor      Usuario?                    @relation(\"CotizacionesEditadas\", fields: [ultimoEditadoPorId], references: [id])\n  createdAt             DateTime                    @default(now())\n  updatedAt             DateTime                    @updatedAt\n  historial             CotizacionHistorial[]\n  notificaciones        Notificacion[]\n\n  @@index([clienteId])\n  // Cubren el WHERE de CotizacionesService.findPendientesDeRecordatorio (cron cada 15 min) y de\n  // AlertasCotizacionesService.avisarRespuestaLenta (cron cada 30 min, ambos en\n  // src/cotizaciones/): columnas de igualdad/IS NULL primero, el rango de fecha al final.\n  @@index([recordatorioEnviadoEn, avisoAlmacenEn, pedidoAprobadoEn])\n  @@index([alertaLentaEnviadaEn, cotizacionEnviadaEn, requerimientoEn])\n  @@map(\"cotizaciones\")\n}\n\n// Historial inmutable de cada cambio a una fecha de etapa o a la proforma. Existe porque el\n// PATCH de Cotizacion permite corregir cualquier campo cuantas veces haga falta (a propósito,\n// para que se pueda cargar tarde) y sin esto no quedaba registro de qué decía antes ni de CUÁNDO\n// se hizo el cambio de verdad (editadoEn es hora de servidor, no la editan ni Joel ni nadie). Es\n// la diferencia real contra el Excel: ahí una celda se pisa sin dejar rastro, acá cada pisada\n// queda escrita para siempre. Ver calcularAlertasCotizacion (alerta CARGA_TARDIA) en\n// cotizaciones.service.ts, que compara editadoEn contra el valor que se cargó.\nmodel CotizacionHistorial {\n  id            Int        @id @default(autoincrement())\n  cotizacionId  Int\n  cotizacion    Cotizacion @relation(fields: [cotizacionId], references: [id], onDelete: Cascade)\n  campo         String\n  valorAnterior String?\n  valorNuevo    String?\n  // Motivo obligatorio cuando un Admin corrige una etapa que Joel ya había marcado (ver\n  // ForbiddenException en cotizaciones.service.ts). Null para el marcado normal (hora real de\n  // servidor, no hace falta justificar) y para ediciones de requerimientoEn/numeroProforma.\n  motivo        String?\n  editadoPorId  Int\n  editadoPor    Usuario    @relation(fields: [editadoPorId], references: [id])\n  editadoEn     DateTime   @default(now())\n\n  @@index([cotizacionId])\n  @@map(\"cotizaciones_historial\")\n}\n\n// Registro de vacaciones/licencias, cargado a mano por un admin cuando alguien\n// sale. Sirve para que Cotizaciones (y a futuro Pedidos) marquen como\n// sospechosa una fecha de etapa que el propio usuario cargó dentro de un\n// período en el que no estaba trabajando — ver calcularAlertas() en\n// cotizaciones.service.ts. No reemplaza ningún sistema de RR.HH., es\n// deliberadamente mínimo: solo lo que hace falta para ese cruce.\nmodel Ausencia {\n  id              Int      @id @default(autoincrement())\n  usuarioId       Int\n  usuario         Usuario  @relation(\"AusenciasDelUsuario\", fields: [usuarioId], references: [id], onDelete: Cascade)\n  desde           DateTime @db.Date // día calendario, inclusive\n  hasta           DateTime @db.Date // día calendario, inclusive\n  motivo          String?\n  registradoPorId Int\n  registradoPor   Usuario  @relation(\"AusenciasRegistradas\", fields: [registradoPorId], references: [id])\n  createdAt       DateTime @default(now())\n\n  @@index([usuarioId])\n  @@map(\"ausencias\")\n}\n\n// ──────────────────────────────────────────\n// MÓDULO KPIs + DOCUMENTACIÓN ISO (Fase 3)\n// Árbol de carpetas dinámico guardado en BD (no hay archivos\n// reales en disco, los documentos van a Supabase Storage).\n// Los permisos se atan al concepto (proceso, o ISO en general),\n// NO a una carpeta puntual — así se heredan solos al clonar un\n// año nuevo. La regla \"PDF visible a todos\" y \"Obsoleto solo\n// Alice\" quedan hardcodeadas en el service (no en tabla), se\n// migran a tabla más adelante si hace falta.\n// ──────────────────────────────────────────\nenum ModuloDocumentos {\n  KPIS\n  ISO\n}\n\nenum TipoCarpeta {\n  ANIO\n  PROCESO\n  PERIODO\n  RI\n  DS\n  OBSOLETO\n}\n\nenum ProcesoIndicador {\n  COMERCIAL\n  COMPRAS\n  ALMACEN_DISTRIBUCION\n  CONTROL_CALIDAD\n  SGC\n  DIRECCION_PLANEAMIENTO\n  RRHH\n  SERVICIOS_GENERALES\n}\n\nenum TipoArchivoDocumento {\n  PDF\n  WORD\n  EXCEL\n  POWERPOINT\n}\n\nmodel Carpeta {\n  id             Int               @id @default(autoincrement())\n  nombre         String\n  carpetaPadreId Int?\n  carpetaPadre   Carpeta?          @relation(\"CarpetaHijos\", fields: [carpetaPadreId], references: [id], onDelete: Cascade)\n  hijos          Carpeta[]         @relation(\"CarpetaHijos\")\n  modulo         ModuloDocumentos\n  tipo           TipoCarpeta?\n  proceso        ProcesoIndicador?\n  archivos       Archivo[]\n  createdAt      DateTime          @default(now())\n  updatedAt      DateTime          @updatedAt\n\n  @@index([carpetaPadreId])\n  @@map(\"carpetas\")\n}\n\nmodel Archivo {\n  id          Int                  @id @default(autoincrement())\n  carpetaId   Int\n  carpeta     Carpeta              @relation(fields: [carpetaId], references: [id], onDelete: Cascade)\n  nombre      String\n  tipo        TipoArchivoDocumento\n  storagePath String\n  subidoPorId Int\n  subidoPor   Usuario              @relation(fields: [subidoPorId], references: [id])\n  fechaSubida DateTime             @default(now())\n\n  @@index([carpetaId])\n  @@map(\"archivos\")\n}\n\nmodel AccesoIndicador {\n  id             Int              @id @default(autoincrement())\n  usuarioId      Int\n  usuario        Usuario          @relation(fields: [usuarioId], references: [id], onDelete: Cascade)\n  proceso        ProcesoIndicador\n  puedeVer       Boolean          @default(false)\n  puedeDescargar Boolean          @default(false)\n  puedeAdjuntar  Boolean          @default(false)\n  puedeEditar    Boolean          @default(false)\n  puedeEliminar  Boolean          @default(false)\n\n  @@unique([usuarioId, proceso])\n  @@map(\"accesos_indicador\")\n}\n\nmodel AccesoISO {\n  id               Int     @id @default(autoincrement())\n  usuarioId        Int     @unique\n  usuario          Usuario @relation(fields: [usuarioId], references: [id], onDelete: Cascade)\n  puedeVer         Boolean @default(false)\n  puedeDescargar   Boolean @default(false)\n  puedeAdjuntar    Boolean @default(false)\n  puedeEditar      Boolean @default(false)\n  puedeEliminar    Boolean @default(false)\n  gestionaObsoleto Boolean @default(false) // ver+editar la carpeta Obsoleto (antes hardcodeado \"solo Alice\")\n\n  @@map(\"accesos_iso\")\n}\n\n// ──────────────────────────────────────────\n// AUDITORÍA DE USUARIOS\n// Quién hizo qué sobre las cuentas (desactivar, reactivar, eliminar, cambiar\n// permisos). A propósito SIN claves foráneas y con los nombres copiados: el\n// registro tiene que sobrevivir a que se elimine el usuario afectado o el admin.\n// ──────────────────────────────────────────\nmodel RegistroAuditoria {\n  id             Int      @id @default(autoincrement())\n  accion         String // USUARIO_DESACTIVADO | USUARIO_REACTIVADO | USUARIO_ELIMINADO | PERMISOS_ACTUALIZADOS\n  actorId        Int?\n  actorNombre    String\n  objetivoId     Int?\n  objetivoNombre String\n  detalle        String?\n  createdAt      DateTime @default(now())\n\n  @@index([createdAt])\n  @@map(\"registro_auditoria\")\n}\n"
}

